document.addEventListener('DOMContentLoaded',()=>{const prefersReducedMotion=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;const svgVisuals=document.querySelectorAll('.sc-case-svg');if(svgVisuals.length){if(prefersReducedMotion||!('IntersectionObserver'in window)){svgVisuals.forEach(svg=>svg.classList.add('is-drawn'));}else{svgVisuals.forEach(svg=>svg.classList.add('js-anim'));const svgObserver=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-drawn');observer.unobserve(entry.target);}});},{root:null,rootMargin:'0px',threshold:0.15});svgVisuals.forEach(svg=>svgObserver.observe(svg));setTimeout(()=>{svgVisuals.forEach(svg=>{const rect=svg.getBoundingClientRect();if(rect.top<window.innerHeight){svg.classList.add('is-drawn');}});},400);}}
const revealElements=document.querySelectorAll('.reveal');if(!revealElements.length)return;const revealObserver=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){const target=entry.target;target.classList.add('is-visible');observer.unobserve(target);}});},{root:null,rootMargin:'0px',threshold:0.1});revealElements.forEach(el=>revealObserver.observe(el));setTimeout(()=>{revealElements.forEach(el=>{const rect=el.getBoundingClientRect();if(rect.top<window.innerHeight){el.classList.add('is-visible');}});},500);});